# Her 17 Nov ("2번 좋은데", "a"): the manuscript look as a trial, only with ?look=manuscript in the address: paper with
# faint staves, the next room circled in the house's coral pencil (lightly tinted pink), a done room ticked by hand.
import sys
P = sys.argv[1]; h = open(P).read()
def rep(a, b, n=1):
    global h
    assert h.count(a) == n, (a[:90], h.count(a)); h = h.replace(a, b)
rep("function thRoomClean(view, state, id, x, y, w, h, fs, out, dimNew, lay, cmp) {\n  const st = state[id], on = id === view.here, done = st === 'done', num = view.nums[id], { tz, sz, pad, sq } = lay;\n  let s = '<rect x=\"' + pFix(x) + '\" y=\"' + pFix(y) + '\" width=\"' + pFix(w) + '\" height=\"' + pFix(h) + '\" fill=\"#fff\" stroke-width=\"1\"/>';\n  if (on) s += '<rect x=\"' + pFix(x + 0.6) + '\" y=\"' + pFix(y + 0.6) + '\" width=\"' + pFix(w - 1.2) + '\" height=\"' + pFix(h - 1.2) + '\" fill=\"#fbdfe3\" stroke=\"none\"/>';",
    "const LOOK_MS = (() => { try { return new URLSearchParams(location.search).get('look') === 'manuscript'; } catch (e) { return false; } })();   // her 17 Nov: the manuscript look, a trial\n"
    "function thRoomClean(view, state, id, x, y, w, h, fs, out, dimNew, lay, cmp) {\n  const st = state[id], on = id === view.here, done = st === 'done', num = view.nums[id], { tz, sz, pad, sq } = lay;\n  let s = '<rect x=\"' + pFix(x) + '\" y=\"' + pFix(y) + '\" width=\"' + pFix(w) + '\" height=\"' + pFix(h) + '\" fill=\"' + (LOOK_MS ? '#fffdf6' : '#fff') + '\" stroke-width=\"1\"/>';\n"
    "  if (LOOK_MS) { const g = cmp ? 3.2 : 4, y0 = y + h - pad * 0.6 - 4 * g; for (let i = 0; i < 5; i++) s += '<line x1=\"' + pFix(x + 5) + '\" x2=\"' + pFix(x + w - 5) + '\" y1=\"' + pFix(y0 + i * g) + '\" y2=\"' + pFix(y0 + i * g) + '\" stroke=\"#e4dcc6\" stroke-width=\"0.6\"/>'; }   // faint staves\n"
    "  if (on) s += '<rect x=\"' + pFix(x + 0.6) + '\" y=\"' + pFix(y + 0.6) + '\" width=\"' + pFix(w - 1.2) + '\" height=\"' + pFix(h - 1.2) + '\" fill=\"' + (LOOK_MS ? '#fdf0f3' : '#fbdfe3') + '\" stroke=\"none\"/>';")
rep("  const nfill = on ? ST.C : dimNew && st === 'new' ? ST.NEW : ST.N;\n  s += stSquare(x + pad, y + pad, sq, view.disp && view.disp[id] != null ? view.disp[id] : num, done ? ST.G : null, cmp ? 9 : 11);",
    "  const nfill = LOOK_MS && done ? '#8b8aa3' : on ? ST.C : dimNew && st === 'new' ? ST.NEW : ST.N;\n  s += stSquare(x + pad, y + pad, sq, view.disp && view.disp[id] != null ? view.disp[id] : num, done && !LOOK_MS ? ST.G : null, cmp ? 9 : 11);\n"
    "  if (LOOK_MS && done) { const tx = x + w - (cmp ? 22 : 28), ty0 = y + (cmp ? 7 : 9), k = cmp ? 0.8 : 1; s += '<path d=\"M' + pFix(tx) + ' ' + pFix(ty0 + 8 * k) + ' q' + pFix(3 * k) + ' ' + pFix(2 * k) + ' ' + pFix(6 * k) + ' ' + pFix(7 * k) + ' q' + pFix(5 * k) + ' -' + pFix(12 * k) + ' ' + pFix(14 * k) + ' -' + pFix(17 * k) + '\" fill=\"none\" stroke=\"#2e8a6e\" stroke-width=\"' + (cmp ? 2 : 2.4) + '\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>'; }   // a hand tick\n"
    "  if (LOOK_MS && on) { const cx = x + w / 2, cy = y + h / 2, rx = w / 2 - 3, ry = h / 2 - 3; s += '<path d=\"M' + pFix(cx - rx * 0.92) + ' ' + pFix(cy + ry * 0.35) + ' C' + pFix(cx - rx * 1.02) + ' ' + pFix(cy - ry * 0.9) + ' ' + pFix(cx + rx * 0.2) + ' ' + pFix(cy - ry * 1.04) + ' ' + pFix(cx + rx * 0.7) + ' ' + pFix(cy - ry * 0.82) + ' S' + pFix(cx + rx * 1.06) + ' ' + pFix(cy + ry * 0.55) + ' ' + pFix(cx + rx * 0.3) + ' ' + pFix(cy + ry * 0.97) + ' S' + pFix(cx - rx * 1.0) + ' ' + pFix(cy + ry * 0.75) + ' ' + pFix(cx - rx * 0.8) + ' ' + pFix(cy - ry * 0.45) + '\" fill=\"none\" stroke=\"' + ST.C + '\" stroke-width=\"' + (cmp ? 1.5 : 1.8) + '\" stroke-linecap=\"round\" opacity=\"0.9\"/>'; }   // the coral pencil ring")
# the page: paper with faint staves behind the house
rep("      <style>{css}</style>\n      {!compact && !noIntro && <PageIntro",
    "      <style>{css + (LOOK_MS ? 'body{background:#fbf6e8 repeating-linear-gradient(transparent 0 22px,#e6dcc2 22px 23px,transparent 23px 29px,#e6dcc2 29px 30px,transparent 30px 36px,#e6dcc2 36px 37px,transparent 37px 43px,#e6dcc2 43px 44px,transparent 44px 50px,#e6dcc2 50px 51px,transparent 51px 92px)!important}' : '')}</style>\n      {!compact && !noIntro && <PageIntro")
open(P, 'w').write(h); print('manuscript trial added')
